def transform(grid):
    g = np.array(grid)
    out = g.copy()
    key = {(0,0):1,(0,1):7,(0,2):6,(1,0):4,(1,2):5,(2,0):2,(2,1):9,(2,2):3}
    for comp in components(g == 0):
        y0, x0, y1, x1 = bbox(comp)
        if y1 - y0 != 4 or x1 - x0 != 4:
            continue
        sq = g[y0:y1+1, x0:x1+1]
        if not ((sq[0] == 0).all() and (sq[4] == 0).all() and (sq[:,0] == 0).all() and (sq[:,4] == 0).all()):
            continue
        for (dy, dx), c in key.items():
            if g[y0+1+dy, x0+1+dx] == 0:
                out[y0+1+dy, x0+1+dx] = c
        emit(out, f"Filled interior 0 cells of the square at ({y0},{x0}) with the fixed positional colour key; centre stays 0.")
    emit(out, "All squares filled.")
    return out
